<?php

declare(strict_types=1);
namespace CetechDeliveryEngine\Tests\Unit\CustomerPolicy;

use CetechDeliveryEngine\Application\Cart\CartDeliverySelectionCapture;
use CetechDeliveryEngine\Application\Selector\ProductDeliveryOption;
use CetechDeliveryEngine\Domain\CustomerContext\CustomerCartContext;
use CetechDeliveryEngine\Domain\PolicyAssignment\PolicyAssignmentState;
use CetechDeliveryEngine\Tests\Support\CustomerPolicy\CustomerPolicyFacadeTestFixture as F;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;
require_once dirname(__DIR__,2).'/Support/CustomerPolicy/CustomerPolicyFacadeTestFixture.php';

final class CustomerPolicyFacadeTest extends TestCase {
	private F$f;
	protected function setUp():void{$this->f=new F();}
	protected function tearDown():void{$this->f->close();}
	private function option(int$id=4,string$key='in_warehouse:delivery:4',string$choice='delivery'):ProductDeliveryOption{return new ProductDeliveryOption($key,'in_warehouse','Available',$choice,'Delivery',$id,'Test delivery',null,null,true,null);}
	private function refuse(callable$work):void{$error=null;try{$work();}catch(\RuntimeException$e){$error=$e;}self::assertInstanceOf(\RuntimeException::class,$error);}
	public function test_off_views_are_inert_before_session_source_or_receipt_access():void{$this->f->enabled=false;self::assertFalse($this->f->facade->enabled());self::assertSame([],$this->f->facade->for_options(33,0,1,[$this->option()]));self::assertSame([],$this->f->facade->for_cart_lines([]));self::assertNull($this->f->facade->for_cart_line('native-key',[]));self::assertFalse($this->f->facade->accept_cart_review('native-key','ticket'));self::assertSame(0,$this->f->bootstrap_calls);self::assertSame([],$this->f->source->transports);self::assertSame([],$this->f->transports);self::assertSame(0,$this->f->native_reads);}
	public function test_pdp_options_share_one_complete_source_batch_and_never_write_receipts():void{$this->f->publish();$views=$this->f->facade->for_options(33,0,1,[$this->option(),$this->option(7,'in_warehouse:delivery:7')]);self::assertSame(['in_warehouse:delivery:4','in_warehouse:delivery:7'],array_keys($views));self::assertCount(1,$this->f->source->transports);self::assertSame(1,$this->f->bootstrap_calls);foreach($views as$v){self::assertSame('ready',$v['status']);self::assertMatchesRegularExpression('/\Acp1p\./',$v['ticket']);self::assertSame('Returns Ω',$v['families']->return_policy_v1['customer_title']);self::assertArrayNotHasKey('name',$v['families']->return_policy_v1);}self::assertSame(0,(int)$this->f->source->base->factory->inspection()->query("SELECT COUNT(*) FROM ".$this->f->source->base->table('options')." WHERE option_name LIKE 'cetech_de_customer_policy_%'")->fetchColumn());}
	public function test_pdp_pickup_and_zero_offer_never_gain_policy_authority():void{$views=$this->f->facade->for_options(33,0,1,[$this->option(4,'pickup','store_pickup'),$this->option(0,'no-offer')]);foreach($views as$v){self::assertSame('unsupported',$v['status']);self::assertNull($v['ticket']);}self::assertSame([],$this->f->source->transports);}
	#[DataProvider('bad_quantities')]
	public function test_invalid_pdp_quantity_is_unavailable_without_a_source_read(mixed$q):void{$v=$this->f->facade->for_options(33,0,$q,[$this->option()]);self::assertSame('unavailable',$v['in_warehouse:delivery:4']['status']);self::assertNull($v['in_warehouse:delivery:4']['ticket']);self::assertSame([],$this->f->source->transports);}
	public static function bad_quantities():array{return[[0],[-1],['1.5'],['01'],[1.5],[INF]];}
	public function test_whole_cart_view_and_per_line_share_exact_immutable_wording_and_ticket():void{$this->f->publish();$this->f->cart->lines=['a'=>$this->f->line('a'),'b'=>$this->f->line('b')];$a=$this->f->facade->for_cart_lines($this->f->cart);$b=$this->f->facade->for_cart_line('a',$this->f->cart->lines['a']);self::assertSame(json_encode($a['a'],JSON_THROW_ON_ERROR),json_encode($b,JSON_THROW_ON_ERROR));self::assertSame('review_required',$b['status']);self::assertCount(1,$this->f->source->transports);self::assertCount(1,$this->f->transports);}
	public function test_posted_or_foreign_cart_line_has_no_product_fallback():void{$this->f->cart->lines=['native-key'=>$this->f->line()];self::assertNull($this->f->facade->for_cart_line('foreign',$this->f->line()));$wrong=$this->f->cart->lines['native-key'];$wrong['quantity']=2;self::assertNull($this->f->facade->for_cart_line('native-key',$wrong));self::assertSame([],$this->f->source->transports);}
	public function test_served_frame_round_trip_never_reissues_unseen_terms_in_one_request():void{$this->f->cart->lines=['native-key'=>$this->f->line()];$first=$this->f->facade->for_cart_lines($this->f->cart);$this->f->cart->lines['native-key']['quantity']=2;$changed=$this->f->facade->for_cart_lines($this->f->cart);self::assertSame('unavailable',$changed['native-key']['status']);self::assertNull($changed['native-key']['ticket']);$this->f->cart->lines['native-key']['quantity']=1;$again=$this->f->facade->for_cart_lines($this->f->cart);self::assertSame('unavailable',$again['native-key']['status']);self::assertNull($again['native-key']['ticket']);self::assertNotNull($first['native-key']['ticket']);self::assertCount(1,$this->f->source->transports);}
	public function test_public_copy_mutation_does_not_change_the_cached_served_view():void{$this->f->publish();$this->f->cart->lines=['native-key'=>$this->f->line()];$a=$this->f->facade->for_cart_lines($this->f->cart);$a['native-key']['families']->return_policy_v1['summary']='Mutated client copy';$b=$this->f->facade->for_cart_lines($this->f->cart);self::assertSame('Original return summary',$b['native-key']['families']->return_policy_v1['summary']);}
	public function test_explicit_review_uses_native_line_then_preflight_freezes_the_original():void{$this->f->cart->lines=['native-key'=>$this->f->line()];$view=$this->f->facade->for_cart_lines($this->f->cart)['native-key'];self::assertTrue($this->f->facade->accept_cart_review('native-key',$view['ticket']));$p=$this->f->facade->prepare_checkout('classic',1);self::assertSame('frozen',$p->state());self::assertSame(['native-key'],array_keys($p->lines()));self::assertSame(1,$this->f->fresh_calls);}
	public function test_review_reconciliation_does_not_eagerly_load_current_policy_again():void{$this->f->cart->lines=['native-key'=>$this->f->line()];$v=$this->f->facade->for_cart_lines($this->f->cart)['native-key'];self::assertTrue($this->f->facade->accept_cart_review('native-key',$v['ticket']));$count=count($this->f->source->transports);self::assertTrue($this->f->facade->accept_cart_review('native-key',$v['ticket']));self::assertCount($count,$this->f->source->transports);}
	public function test_current_source_change_after_review_refuses_before_original_creation():void{$this->f->cart->lines=['native-key'=>$this->f->line()];$v=$this->f->facade->for_cart_lines($this->f->cart)['native-key'];self::assertTrue($this->f->facade->accept_cart_review('native-key',$v['ticket']));$this->f->source->seed(PolicyAssignmentState::make_coordinate(1,'product',33),['mode'=>'disabled']);$this->refuse(fn()=>$this->f->facade->prepare_checkout('classic',1));self::assertNull($this->f->receipts->active_original($this->f->authority->session_owner()));}
	public function test_unreviewed_checkout_never_freezes_an_original():void{$this->f->cart->lines=['native-key'=>$this->f->line()];$this->refuse(fn()=>$this->f->facade->prepare_checkout('store_api',1));self::assertNull($this->f->receipts->active_original($this->f->authority->session_owner()));}
	public function test_absent_or_false_fresh_admission_refuses_applicable_new_capture():void{foreach([false,true]as$port){$f=new F($port);try{$f->fresh=false;$f->cart->lines=['native-key'=>$f->line()];$this->refuse(fn()=>$f->facade->prepare_checkout('classic',1));self::assertSame([],$f->source->transports);}finally{$f->close();}}}
	public function test_no_eligible_native_line_returns_null_without_source_or_fresh_admission():void{$this->f->cart->lines=['ordinary'=>['product_id'=>33,'quantity'=>1]];self::assertSame([],$this->f->facade->for_cart_lines($this->f->cart));self::assertNull($this->f->facade->prepare_checkout('classic',1));self::assertSame(0,$this->f->fresh_calls);self::assertSame([],$this->f->source->transports);}
	#[DataProvider('unsupported_cart')]
	public function test_unsupported_cart_frames_refuse_without_original_capture(string$mode):void{$this->f->cart->lines=['native-key'=>$this->f->line()];switch($mode){case'fee':$this->f->cart->fees=[['amount'=>1]];break;case'coupon':$this->f->cart->coupons=['OWNED'];break;case'mixed':$this->f->cart->lines['ordinary']=['product_id'=>34,'quantity'=>1];break;case'fractional':$this->f->cart->lines['native-key']['quantity']=1.5;break;case'quote':$this->f->cart->lines['native-key']['_cetech_de_quote_private']='attempt';break;case'policy-marker':$this->f->cart->lines['native-key']['_cetech_de_policy_packet']='attempt';break;case'pickup':$this->f->cart->lines['pickup']=$this->f->line('pickup',[CustomerCartContext::CART_KEY=>CustomerCartContext::pickup(2)->toArray()]);break;}$this->refuse(fn()=>$this->f->facade->prepare_checkout('classic',1));self::assertNull($this->f->receipts->active_original($this->f->authority->session_owner()));}
	public static function unsupported_cart():array{return[['fee'],['coupon'],['mixed'],['fractional'],['quote'],['policy-marker'],['pickup']];}
	public function test_saved_legacy_order_with_flag_off_has_no_current_session_or_factory_read():void{$this->f->enabled=false;$this->f->visible=false;$order=new \WC_Order(123);self::assertSame([],$this->f->facade->saved_order($order,static fn():bool=>true));self::assertSame(0,$this->f->native_reads);self::assertSame(0,$this->f->factory_reads);self::assertSame([],$this->f->source->transports);}
	public function test_saved_unauthorized_order_refuses_before_private_reader_or_source():void{$this->f->enabled=false;$this->refuse(fn()=>$this->f->facade->saved_order(new \WC_Order(123),static fn():bool=>false));self::assertSame(0,$this->f->factory_reads);self::assertSame([],$this->f->source->transports);}
}
